{
  "name": "@air-bizapps/opencode-plugin-vision",
  "version": "1.1.0",
  "description": "OpenCode plugin that enables image/vision capabilities for OpenAI-compatible custom providers",
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "vision",
    "image",
    "openai-compatible",
    "custom-provider"
  ],
  "author": "TwinForge",
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.3",
    "@types/node": "^24.0.0",
    "typescript": "^5.8.0"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/air-bizapps/opencode-plugin-vision"
  }
}
